package main
type N int
type P struct{V int}
func arrayView() int { a:=[3]int{2,3,7}; p:=&a; s:=p[1:]; q:=(*[2]int)(s); q[0]=6; return 100*a[1]+10*p[2]+(*q)[0] }
func mapKeys() int { m:=map[any]int{int(1):2,N(1):3}; n:=map[P]int{{2}:9}; return m[int(1)]*100+m[N(1)]*10+n[P{2}] }
func dynamicKey() bool { a:=[1]any{int(1)}; b:=[1]any{N(1)}; return a==b }
func drained() int {c:=make(chan int,2);c<-3;c<-7;close(c);n:=0;for v:=range c {n=10*n+v};return n}
func openChannel() int { c:=make(chan int,1);c<-2; for range c{};return 5 }
func zeroPointer() bool { s:=[]int{};return (*[0]int)(s)!=nil }
func shortSlice() int {s:=[]int{1};p:=(*[2]int)(s);return p[0]}
